"""Regenerate fixed, fully synthetic SQLite/WAL contract-stress fixtures."""

from base64 import b64decode, b64encode
from pathlib import Path
from zlib import decompress

_COMPRESSED_FIXTURES = {
    "opencode.db": "eNoLDvTJLElVSMsvyk0sUTBmYGFgYmJwUFBgYGBghGJKACOD3tRTvCAWC8MoGAWjYJABAJMbB1g=",
    "opencode.db-wal": "",
}

FIXTURES = {
    name: b64encode(decompress(b64decode(encoded))).decode()
    for name, encoded in _COMPRESSED_FIXTURES.items()
}


def main() -> None:
    root = Path(__file__).parent
    for name, encoded in FIXTURES.items():
        (root / name).write_bytes(b64decode(encoded))


if __name__ == "__main__":
    main()
